import{_ as l,C as h,o as a,c,a9 as r,b as i,w as t,a as n,E as s,a8 as d}from"./chunks/framework.BOiBTRPC.js";const b=JSON.parse('{"title":"Spark Deep Dive — Track Overview","description":"The 20% of Spark that explains 80% of production performance — architecture, Catalyst, shuffles, joins, AQE, and the tuning playbook.","frontmatter":{"title":"Spark Deep Dive — Track Overview","description":"The 20% of Spark that explains 80% of production performance — architecture, Catalyst, shuffles, joins, AQE, and the tuning playbook."},"headers":[],"relativePath":"spark/index.md","filePath":"spark/index.md"}'),p={name:"spark/index.md"};function u(g,e,m,f,k,w){const o=h("Mermaid");return a(),c("div",null,[e[2]||(e[2]=r('<h1 id="spark-deep-dive" tabindex="-1">Spark Deep Dive <a class="header-anchor" href="#spark-deep-dive" aria-label="Permalink to &quot;Spark Deep Dive&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Spark is still the default distributed compute engine for lakehouses, ETL fleets, and ML feature pipelines. The difference between a job that costs $3 and one that costs $300 is rarely the code — it&#39;s whether the author understands shuffles, join strategies, and what the optimizer actually did.</p></blockquote><h2 id="who-this-track-is-for" tabindex="-1">Who this track is for <a class="header-anchor" href="#who-this-track-is-for" aria-label="Permalink to &quot;Who this track is for&quot;">​</a></h2><p>Engineers who can already write a Spark job but can&#39;t yet answer <em>why it was slow</em>. The target reader has run PySpark or Spark SQL in production, has stared at the Spark UI without knowing which numbers matter, and wants to reach the level where a slow stage is diagnosed in minutes, not days.</p><h2 id="track-map" tabindex="-1">Track map <a class="header-anchor" href="#track-map" aria-label="Permalink to &quot;Track map&quot;">​</a></h2>',5)),(a(),i(d,null,{default:t(()=>[s(o,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%221%20%C2%B7%20Architecture%20%26%20Execution%22%5D%20--%3E%20B%5B%222%20%C2%B7%20Catalyst%2C%20Shuffle%20%26%20Joins%22%5D%0A%20%20B%20--%3E%20C%5B%223%20%C2%B7%20Performance%20Optimization%22%5D%0A%20%20C%20--%3E%20D%5B%224%20%C2%B7%20Advanced%20Spark%20Algorithms%22%5D%0A%20%20A%20-.-%3E%7C%22driver%20%2F%20executors%20%2F%20stages%22%7C%20C%0A%20%20C%20-.-%3E%7C%22tuning%20knobs%22%7C%20D%0A%20%20B%20-.-%3E%7C%22explain%20plans%20%2F%20joins%22%7C%20C%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<table tabindex="0"><thead><tr><th>Chapter</th><th>You will be able to</th></tr></thead><tbody><tr><td><a href="/Data-Knowledge/spark/architecture.html">Architecture &amp; Execution</a></td><td>Diagram a Spark app (driver, executors, slots), explain jobs→stages→tasks, narrow vs wide deps, unified memory, DSv2, and the configs that actually matter.</td></tr><tr><td><a href="/Data-Knowledge/spark/execution.html">Catalyst, Shuffle &amp; Joins</a></td><td>Trace a query through Catalyst, read <code>explain(True)</code>, choose the right join strategy, and control partitioning (repartition, coalesce, salting, bucketing).</td></tr><tr><td><a href="/Data-Knowledge/spark/optimization.html">Performance Optimization</a></td><td>Read the Spark UI like a profiler, apply the skew playbook, use AQE config keys, pick storage levels, kill small files, and work a tuning checklist ordered by impact.</td></tr><tr><td><a href="/Data-Knowledge/spark/advanced-algorithms.html">Advanced Spark Algorithms</a></td><td>Do the salting math for a hot key, control lineage in iterative algorithms (PageRank, connected components), explain the join cost model, use Z-order/bucketing for file pruning, and reason about Tungsten whole-stage codegen and CBO statistics.</td></tr></tbody></table><h2 id="pareto-focus-—-what-actually-matters" tabindex="-1">Pareto focus — what actually matters <a class="header-anchor" href="#pareto-focus-—-what-actually-matters" aria-label="Permalink to &quot;Pareto focus — what actually matters&quot;">​</a></h2><ul><li><strong>Shuffles are the price of everything.</strong> Wide dependencies create stages, stages serialize work, and every slow Spark job is a shuffle story.</li><li><strong>Join strategy is a decision, not a detail.</strong> Broadcast → shuffle-hash → sort-merge is a cost ladder; knowing when Catalyst picks wrong (and how to hint it) is the single highest-leverage skill.</li><li><strong>Data skew is the #1 production failure mode.</strong> One hot key = one 40-minute task while 199 executors idle. Salting, broadcasting, and isolating are the fixes; AQE&#39;s skew-split is the safety net.</li><li><strong>AQE changes the mental model.</strong> Since Spark 3, plans are re-optimized at runtime from real statistics — coalescing partitions, switching join strategies, splitting skew. Know what it fixes and what it can&#39;t.</li><li><strong>Memory is unified but not free.</strong> Execution vs storage memory, spill to disk, and the difference between <code>cache()</code>, <code>persist()</code>, and <code>checkpoint()</code> decide whether a job finishes or OOMs.</li><li><strong><code>repartition</code> ≠ <code>coalesce</code>.</strong> One shuffles, one doesn&#39;t — and picking wrong either adds a full shuffle or creates 200 tiny files.</li><li><strong>The Spark UI is the profiler.</strong> Stage time, shuffle read/write, spill, GC, and task time distribution tell you the failure class before you touch code.</li></ul><h2 id="suggested-path" tabindex="-1">Suggested path <a class="header-anchor" href="#suggested-path" aria-label="Permalink to &quot;Suggested path&quot;">​</a></h2><ol><li>Read <a href="/Data-Knowledge/spark/architecture.html">Architecture &amp; Execution</a> until you can draw the runtime without notes.</li><li>Read <a href="/Data-Knowledge/spark/execution.html">Catalyst, Shuffle &amp; Joins</a> until <code>explain(True)</code> output stops looking like noise.</li><li>Read <a href="/Data-Knowledge/spark/optimization.html">Performance Optimization</a> with a slow job of yours open in the Spark UI.</li><li>Read <a href="/Data-Knowledge/spark/advanced-algorithms.html">Advanced Spark Algorithms</a> when you want the <em>why</em> underneath the knobs — salting, iterative lineage, codegen, Z-order.</li></ol><p>Every chapter ends with a quiz calibrated to what senior interviews actually ask.</p><h2 id="build-one-project-end-to-end-the-best-way-to-learn-spark" tabindex="-1">Build one project end-to-end (the best way to learn Spark) <a class="header-anchor" href="#build-one-project-end-to-end-the-best-way-to-learn-spark" aria-label="Permalink to &quot;Build one project end-to-end (the best way to learn Spark)&quot;">​</a></h2><p><em>Spark in Action</em> is organized around a simple arc — ingest → transform → aggregate → export — and the fastest way to internalize this track is to run one small pipeline through every chapter. Pick a public dataset you can hold in your head: web-server access logs, GHCN weather CSVs, or GitHub events JSON.</p>',8)),(a(),i(d,null,{default:t(()=>[s(o,{id:"mermaid-138",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22Read%20raw%20JSON%20or%20CSV%20logs%22%5D%20--%3E%20B%5B%22Clean%20and%20type%20the%20records%22%5D%0A%20%20B%20--%3E%20C%5B%22Aggregate%20per%20key%20and%20window%22%5D%0A%20%20C%20--%3E%20D%5B%22Export%20parquet%20or%20Delta%20table%22%5D%0A%20%20A%20-.-%3E%7C%22ch%201%20%C2%B7%20architecture%22%7C%20B%0A%20%20B%20-.-%3E%7C%22ch%202%20%C2%B7%20explain%20plans%22%7C%20C%0A%20%20C%20-.-%3E%7C%22ch%203%20%C2%B7%20tuning%22%7C%20D%0A%20%20D%20-.-%3E%7C%22ch%204%20%C2%B7%20salting%20and%20Z-order%22%7C%20C%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<table tabindex="0"><thead><tr><th>Project step</th><th>Do this</th><th>Chapter to read first</th></tr></thead><tbody><tr><td>Ingest</td><td><code>spark.read.json(...)</code> / <code>.csv(...)</code> on raw logs; inspect the inferred schema, then supply your own</td><td><a href="/Data-Knowledge/spark/architecture.html">Architecture &amp; Execution</a> — know what the driver and executors just did</td></tr><tr><td>Clean</td><td>Filter, cast timestamps, dedupe; chain transformations and notice nothing runs yet</td><td><a href="/Data-Knowledge/spark/execution.html">Catalyst, Shuffle &amp; Joins</a> — laziness is a feature; read <code>explain(True)</code> on your chain</td></tr><tr><td>Aggregate</td><td><code>groupBy</code> a key, count per window, join to a small dimension table</td><td><a href="/Data-Knowledge/spark/execution.html">Catalyst, Shuffle &amp; Joins</a> — the shuffle you just triggered; <a href="/Data-Knowledge/spark/optimization.html">Performance Optimization</a> for the Spark UI read</td></tr><tr><td>Export</td><td>Write partitioned parquet; check file sizes on disk</td><td><a href="/Data-Knowledge/spark/optimization.html">Performance Optimization</a> — <code>repartition</code> vs <code>coalesce</code>, small-file problem</td></tr><tr><td>Stretch goal</td><td>Salt a hot key, Z-order the output, cache an iterative step</td><td><a href="/Data-Knowledge/spark/advanced-algorithms.html">Advanced Spark Algorithms</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Common beginner traps from the book</p><ul><li><strong><code>collect()</code> on big data</strong> — it pulls everything to the driver; use it for a handful of rows (<code>show()</code>, <code>take(n)</code>) and let executors do the work.</li><li><strong>Driving everything through one dataframe</strong> — chaining fifty transformations on one <code>df</code> builds a giant logical plan nobody can debug; materialize intermediate results with names you can find in the UI.</li><li><strong>Never running <code>explain()</code></strong> — the physical plan is the cheapest diagnostic you have; if you can&#39;t read it, you can&#39;t tune the job.</li><li><strong><code>local[*]</code> habits in prod</strong> — <code>local</code> mode is for learning; hardcoding the master (or defaults sized for your laptop) into a deployed app is how jobs silently run on one core.</li><li><strong>Expecting Spark to &quot;just work&quot; like a database</strong> — Spark does lazy, distributed computation, not magic; a transformation you don&#39;t understand becomes a stage you can&#39;t explain.</li></ul></div><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><strong>Spark in Action, Second Edition</strong> — Jean-Georges Perrin (2020), <a href="https://www.manning.com/books/spark-in-action-second-edition" target="_blank" rel="noreferrer">Manning</a></li></ul>',4))])}const C=l(p,[["render",u]]);export{b as __pageData,C as default};
